1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Damage = {
9	  itemType: string;
10	  amount: number;
11	};
12	
13	export type Step =
14	  | { op: "quote"; items: Item[] }
15	  | { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };
16	
17	export type Scenario = {
18	  customer: { yearsWithMHPCO: number };
19	  steps: Step[];
20	};
21	
22	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
23	
24	const PROCESSING_FEE = 5;
25	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
26	
27	const BASE_PREMIUMS: Record<string, number> = {
28	  sword: 100,
29	  amulet: 60,
30	};
31	
32	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
33	
34	const quotePremium = (items: Item[]): number => {
35	  const policyBasePremium = items.reduce(
36	    (sum, item) => sum + basePremiumOf(item),
37	    0,
38	  );
39	  const firstInsuranceSurcharge =
40	    (policyBasePremium * FIRST_INSURANCE_SURCHARGE_PERCENT) / 100;
41	
42	  return Math.ceil(
43	    policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE,
44	  );
45	};
46	
47	export const runScenario = (scenario: Scenario): StepResult[] =>
48	  scenario.steps.map((step) => {
49	    if (step.op === "quote") return { premium: quotePremium(step.items) };
50	    throw new Error(`Unsupported step: ${step.op}`);
51	  });
